/* X25519 (RFC 7748) over GF(2^255-19) with ten signed 32-bit limbs.
 *
 * Limb k holds bits ceil(25.5 k) .. ceil(25.5 (k+1)) - 1: 26 bits for even k,
 * 25 for odd k (the ref10 layout). Products are 32x32->64, which the PPC750
 * does natively; Everest's 51-bit limbs need 64x64->128 and emulate it on
 * PPC32. Field multiply and square are generated by tools/gen_fe25519.py.
 *
 * Bounds: a "carried" element (output of fe_mul, fe_sq, fe_mul121665,
 * fe_frombytes) has |limb| <= about 2^25 (even) / 2^24 (odd). fe_mul and
 * fe_sq accept inputs up to 1.65 * 2^26 / 2^25, which covers one fe_add or
 * fe_sub of carried elements; the ladder never feeds them anything else.
 *
 * Constant time: no branch or table index depends on the scalar or the point;
 * the ladder swaps with a mask. */
#include <stdint.h>
#include <string.h>

#include "accel/wtls_x25519.h"

typedef int32_t fe[10];

/* Signed right shift is arithmetic on every compiler libwiitls supports (GCC
 * defines it); shifts of negative values to the left are written as products
 * to stay out of undefined behaviour. */
#define CARRY26(a, b)                          \
    do {                                       \
        int64_t c_ = ((a) + (1 << 25)) >> 26;  \
        (b) += c_;                             \
        (a) -= c_ * ((int64_t)1 << 26);        \
    } while (0)
#define CARRY25(a, b)                          \
    do {                                       \
        int64_t c_ = ((a) + (1 << 24)) >> 25;  \
        (b) += c_;                             \
        (a) -= c_ * ((int64_t)1 << 25);        \
    } while (0)

/* Carry 64-bit limb sums into a carried element (the ref10 order: two
 * interleaved chains keep every intermediate in range). */
static inline void fe_carry_wide(fe h, int64_t h0, int64_t h1, int64_t h2, int64_t h3, int64_t h4,
                                 int64_t h5, int64_t h6, int64_t h7, int64_t h8, int64_t h9) {
    CARRY26(h0, h1);
    CARRY26(h4, h5);
    CARRY25(h1, h2);
    CARRY25(h5, h6);
    CARRY26(h2, h3);
    CARRY26(h6, h7);
    CARRY25(h3, h4);
    CARRY25(h7, h8);
    CARRY26(h4, h5);
    CARRY26(h8, h9);
    {
        int64_t c = (h9 + (1 << 24)) >> 25;
        h0 += c * 19;
        h9 -= c * ((int64_t)1 << 25);
    }
    CARRY26(h0, h1);
    h[0] = (int32_t)h0;
    h[1] = (int32_t)h1;
    h[2] = (int32_t)h2;
    h[3] = (int32_t)h3;
    h[4] = (int32_t)h4;
    h[5] = (int32_t)h5;
    h[6] = (int32_t)h6;
    h[7] = (int32_t)h7;
    h[8] = (int32_t)h8;
    h[9] = (int32_t)h9;
}

#include "accel/fe25519_mul.inc"

static void fe_add(fe h, const fe f, const fe g) {
    for (int i = 0; i < 10; i++) h[i] = f[i] + g[i];
}

static void fe_sub(fe h, const fe f, const fe g) {
    for (int i = 0; i < 10; i++) h[i] = f[i] - g[i];
}

/* h = 121665 * f: (A - 2) / 4 for Curve25519, the a24 of RFC 7748. */
static void fe_mul121665(fe h, const fe f) {
    int64_t t[10];
    for (int i = 0; i < 10; i++) t[i] = (int64_t)f[i] * 121665;
    fe_carry_wide(h, t[0], t[1], t[2], t[3], t[4], t[5], t[6], t[7], t[8], t[9]);
}

/* h = f^(2^n) */
static void fe_sqn(fe h, const fe f, int n) {
    fe_sq(h, f);
    for (int i = 1; i < n; i++) fe_sq(h, h);
}

/* out = z^(p-2) = z^(2^255 - 21) = 1/z (0 for z = 0). */
static void fe_invert(fe out, const fe z) {
    fe t0, t1, t2, t3;
    fe_sq(t0, z);           /* 2 */
    fe_sqn(t1, t0, 2);      /* 8 */
    fe_mul(t1, z, t1);      /* 9 */
    fe_mul(t0, t0, t1);     /* 11 */
    fe_sq(t2, t0);          /* 22 */
    fe_mul(t1, t1, t2);     /* 2^5 - 1 */
    fe_sqn(t2, t1, 5);
    fe_mul(t1, t2, t1);     /* 2^10 - 1 */
    fe_sqn(t2, t1, 10);
    fe_mul(t2, t2, t1);     /* 2^20 - 1 */
    fe_sqn(t3, t2, 20);
    fe_mul(t2, t3, t2);     /* 2^40 - 1 */
    fe_sqn(t2, t2, 10);
    fe_mul(t1, t2, t1);     /* 2^50 - 1 */
    fe_sqn(t2, t1, 50);
    fe_mul(t2, t2, t1);     /* 2^100 - 1 */
    fe_sqn(t3, t2, 100);
    fe_mul(t2, t3, t2);     /* 2^200 - 1 */
    fe_sqn(t2, t2, 50);
    fe_mul(t1, t2, t1);     /* 2^250 - 1 */
    fe_sqn(t1, t1, 5);      /* 2^255 - 2^5 */
    fe_mul(out, t1, t0);    /* 2^255 - 21 */
}

static uint32_t load3(const uint8_t *s) {
    return (uint32_t)s[0] | (uint32_t)s[1] << 8 | (uint32_t)s[2] << 16;
}

static uint32_t load4(const uint8_t *s) {
    return load3(s) | (uint32_t)s[3] << 24;
}

/* Little-endian 255-bit integer (bit 255 ignored) -> carried element. The
 * value may be >= p; the arithmetic is mod p either way. */
static void fe_frombytes(fe h, const uint8_t s[32]) {
    fe_carry_wide(h, (int64_t)load4(s), (int64_t)load3(s + 4) << 6, (int64_t)load3(s + 7) << 5,
                  (int64_t)load3(s + 10) << 3, (int64_t)load3(s + 13) << 2, (int64_t)load4(s + 16),
                  (int64_t)load3(s + 20) << 7, (int64_t)load3(s + 23) << 5, (int64_t)load3(s + 26) << 4,
                  (int64_t)(load3(s + 29) & 0x7fffff) << 2);
}

/* Carried element -> canonical little-endian bytes (fully reduced mod p). */
static void fe_tobytes(uint8_t s[32], const fe f) {
    int32_t h[10];
    memcpy(h, f, sizeof h);
    /* q = floor(h / p), 0 or 1 for a carried element: h - q p is canonical. */
    int32_t q = (19 * h[9] + (1 << 24)) >> 25;
    for (int i = 0; i < 10; i++) q = (h[i] + q) >> ((i & 1) ? 25 : 26);
    h[0] += 19 * q;
    for (int i = 0; i < 9; i++) {
        int bits = (i & 1) ? 25 : 26;
        int32_t c = h[i] >> bits;
        h[i + 1] += c;
        h[i] -= c * (1 << bits);
    }
    h[9] -= (h[9] >> 25) * (1 << 25);
    /* Now 0 <= h[k] < 2^26 / 2^25: pack bit by bit position. */
    uint32_t u[10];
    for (int i = 0; i < 10; i++) u[i] = (uint32_t)h[i];
    s[0] = (uint8_t)u[0];
    s[1] = (uint8_t)(u[0] >> 8);
    s[2] = (uint8_t)(u[0] >> 16);
    s[3] = (uint8_t)((u[0] >> 24) | (u[1] << 2));
    s[4] = (uint8_t)(u[1] >> 6);
    s[5] = (uint8_t)(u[1] >> 14);
    s[6] = (uint8_t)((u[1] >> 22) | (u[2] << 3));
    s[7] = (uint8_t)(u[2] >> 5);
    s[8] = (uint8_t)(u[2] >> 13);
    s[9] = (uint8_t)((u[2] >> 21) | (u[3] << 5));
    s[10] = (uint8_t)(u[3] >> 3);
    s[11] = (uint8_t)(u[3] >> 11);
    s[12] = (uint8_t)((u[3] >> 19) | (u[4] << 6));
    s[13] = (uint8_t)(u[4] >> 2);
    s[14] = (uint8_t)(u[4] >> 10);
    s[15] = (uint8_t)(u[4] >> 18);
    s[16] = (uint8_t)u[5];
    s[17] = (uint8_t)(u[5] >> 8);
    s[18] = (uint8_t)(u[5] >> 16);
    s[19] = (uint8_t)((u[5] >> 24) | (u[6] << 1));
    s[20] = (uint8_t)(u[6] >> 7);
    s[21] = (uint8_t)(u[6] >> 15);
    s[22] = (uint8_t)((u[6] >> 23) | (u[7] << 3));
    s[23] = (uint8_t)(u[7] >> 5);
    s[24] = (uint8_t)(u[7] >> 13);
    s[25] = (uint8_t)((u[7] >> 21) | (u[8] << 4));
    s[26] = (uint8_t)(u[8] >> 4);
    s[27] = (uint8_t)(u[8] >> 12);
    s[28] = (uint8_t)((u[8] >> 20) | (u[9] << 6));
    s[29] = (uint8_t)(u[9] >> 2);
    s[30] = (uint8_t)(u[9] >> 10);
    s[31] = (uint8_t)(u[9] >> 18);
}

/* Hides v from the optimiser. Without it GCC -O3 for the PPC750 sees that a
 * mask comes from a 0/1 value and compiles the masked swap back into a branch
 * on the scalar bit (tools/check_ct.cmake checks the Wii object for that). */
static inline int32_t value_barrier(int32_t v) {
#if defined(__GNUC__)
    __asm__("" : "+r"(v));
#endif
    return v;
}

/* Swap f and g when b == 1, without a branch. */
static void fe_cswap(fe f, fe g, uint32_t b) {
    int32_t mask = value_barrier(-(int32_t)b);
    for (int i = 0; i < 10; i++) {
        int32_t x = mask & (f[i] ^ g[i]);
        f[i] ^= x;
        g[i] ^= x;
    }
}

/* ---- Fixed base: Edwards comb (public key of a fresh key pair) ----------
 *
 * u(k * 9) on Curve25519 equals (1 + y) / (1 - y) of k * B on the birationally
 * equivalent twisted Edwards curve -x^2 + y^2 = 1 + d x^2 y^2. There, k * B is
 * a sum of 64 table points (k in signed radix 16, k_base[i][j] = (j+1) 256^i B):
 * 64 mixed additions and 4 doublings instead of 255 ladder steps. Same
 * algorithm as ref10's ge_scalarmult_base; the table is generated. */

typedef struct {
    fe yplusx, yminusx, xy2d;
} ge_precomp;

typedef struct {
    fe X, Y, Z, T; /* extended: x = X/Z, y = Y/Z, xy = T/Z */
} ge_p3;

typedef struct {
    fe X, Y, Z; /* projective */
} ge_p2;

typedef struct {
    fe X, Y, Z, T; /* completed: x = X/Z, y = Y/T */
} ge_p1p1;

#include "accel/ge25519_base.inc"

static void fe_carry(fe h) {
    fe_carry_wide(h, h[0], h[1], h[2], h[3], h[4], h[5], h[6], h[7], h[8], h[9]);
}

/* h = 2 f^2, carried. */
static void fe_sq2(fe h, const fe f) {
    fe_sq(h, f);
    fe_add(h, h, h);
    fe_carry(h);
}

static void fe_cmov(fe f, const fe g, uint32_t b) {
    int32_t mask = value_barrier(-(int32_t)b);
    for (int i = 0; i < 10; i++) f[i] ^= mask & (f[i] ^ g[i]);
}

static void ge_p1p1_to_p2(ge_p2 *r, const ge_p1p1 *p) {
    fe_mul(r->X, p->X, p->T);
    fe_mul(r->Y, p->Y, p->Z);
    fe_mul(r->Z, p->Z, p->T);
}

static void ge_p1p1_to_p3(ge_p3 *r, const ge_p1p1 *p) {
    fe_mul(r->X, p->X, p->T);
    fe_mul(r->Y, p->Y, p->Z);
    fe_mul(r->Z, p->Z, p->T);
    fe_mul(r->T, p->X, p->Y);
}

static void ge_p2_dbl(ge_p1p1 *r, const ge_p2 *p) {
    fe t0;
    fe_sq(r->X, p->X);
    fe_sq(r->Z, p->Y);
    fe_sq2(r->T, p->Z);
    fe_add(r->Y, p->X, p->Y);
    fe_sq(t0, r->Y);
    fe_add(r->Y, r->Z, r->X);
    fe_sub(r->Z, r->Z, r->X);
    fe_sub(r->X, t0, r->Y);
    fe_sub(r->T, r->T, r->Z);
}

/* r = p + q (mixed: q affine, precomputed). */
static void ge_madd(ge_p1p1 *r, const ge_p3 *p, const ge_precomp *q) {
    fe t0;
    fe_add(r->X, p->Y, p->X);
    fe_sub(r->Y, p->Y, p->X);
    fe_mul(r->Z, r->X, q->yplusx);
    fe_mul(r->Y, r->Y, q->yminusx);
    fe_mul(r->T, q->xy2d, p->T);
    fe_add(t0, p->Z, p->Z);
    fe_sub(r->X, r->Z, r->Y);
    fe_add(r->Y, r->Z, r->Y);
    fe_add(r->Z, t0, r->T);
    fe_sub(r->T, t0, r->T);
}

static uint32_t eq8(int32_t a, int32_t b) {
    return ((uint32_t)(a ^ b) - 1u) >> 31; /* 1 iff a == b (both in 0..255) */
}

/* t = b * k_base[pos][.] for b in -8..8, reading every entry (constant time). */
static void ge_select(ge_precomp *t, int pos, int32_t b) {
    uint32_t neg = (uint32_t)b >> 31;
    int32_t babs = b - (int32_t)((-(int32_t)neg & b) * 2); /* |b| */
    memset(t, 0, sizeof *t);
    t->yplusx[0] = 1; /* neutral element: (1, 1, 0) */
    t->yminusx[0] = 1;
    for (int j = 0; j < 8; j++) {
        uint32_t m = eq8(babs, j + 1);
        fe_cmov(t->yplusx, k_base[pos][j].yplusx, m);
        fe_cmov(t->yminusx, k_base[pos][j].yminusx, m);
        fe_cmov(t->xy2d, k_base[pos][j].xy2d, m);
    }
    /* -P = (y-x, y+x, -2dxy) */
    ge_precomp minus;
    memcpy(minus.yplusx, t->yminusx, sizeof(fe));
    memcpy(minus.yminusx, t->yplusx, sizeof(fe));
    for (int i = 0; i < 10; i++) minus.xy2d[i] = -t->xy2d[i];
    fe_cmov(t->yplusx, minus.yplusx, neg);
    fe_cmov(t->yminusx, minus.yminusx, neg);
    fe_cmov(t->xy2d, minus.xy2d, neg);
}

/* out = u(k * B) for a clamped scalar k. */
static void x25519_base(uint8_t out[32], const uint8_t k[32]) {
    int8_t e[64];
    for (int i = 0; i < 32; i++) {
        e[2 * i] = (int8_t)(k[i] & 15);
        e[2 * i + 1] = (int8_t)(k[i] >> 4);
    }
    /* Signed digits in -8..7 (the last in -8..8): sum e[i] 16^i = k. */
    int8_t carry = 0;
    for (int i = 0; i < 63; i++) {
        e[i] = (int8_t)(e[i] + carry);
        carry = (int8_t)((e[i] + 8) >> 4);
        e[i] = (int8_t)(e[i] - carry * 16);
    }
    e[63] = (int8_t)(e[63] + carry);

    ge_p3 h;
    ge_p1p1 r;
    ge_p2 s;
    ge_precomp t;
    memset(&h, 0, sizeof h);
    h.Y[0] = 1;
    h.Z[0] = 1;
    for (int i = 1; i < 64; i += 2) {
        ge_select(&t, i / 2, e[i]);
        ge_madd(&r, &h, &t);
        ge_p1p1_to_p3(&h, &r);
    }
    /* h *= 16 */
    memcpy(s.X, h.X, sizeof(fe));
    memcpy(s.Y, h.Y, sizeof(fe));
    memcpy(s.Z, h.Z, sizeof(fe));
    ge_p2_dbl(&r, &s);
    ge_p1p1_to_p2(&s, &r);
    ge_p2_dbl(&r, &s);
    ge_p1p1_to_p2(&s, &r);
    ge_p2_dbl(&r, &s);
    ge_p1p1_to_p2(&s, &r);
    ge_p2_dbl(&r, &s);
    ge_p1p1_to_p3(&h, &r);
    for (int i = 0; i < 64; i += 2) {
        ge_select(&t, i / 2, e[i]);
        ge_madd(&r, &h, &t);
        ge_p1p1_to_p3(&h, &r);
    }

    /* u = (Z + Y) / (Z - Y). Never 0/0: a clamped k is no multiple of the
     * group order. */
    fe num, den;
    fe_add(num, h.Z, h.Y);
    fe_sub(den, h.Z, h.Y);
    fe_carry(num);
    fe_carry(den);
    fe_invert(den, den);
    fe_mul(num, num, den);
    fe_tobytes(out, num);

    volatile int8_t *ve = e;
    for (int i = 0; i < 64; i++) ve[i] = 0;
    volatile uint8_t *vh = (volatile uint8_t *)&h;
    for (size_t i = 0; i < sizeof h; i++) vh[i] = 0;
    volatile uint8_t *vt = (volatile uint8_t *)&t;
    for (size_t i = 0; i < sizeof t; i++) vt[i] = 0;
    volatile uint8_t *vr = (volatile uint8_t *)&r;
    for (size_t i = 0; i < sizeof r; i++) vr[i] = 0;
    volatile uint8_t *vs = (volatile uint8_t *)&s;
    for (size_t i = 0; i < sizeof s; i++) vs[i] = 0;
    volatile int32_t *vnum = num, *vden = den;
    for (int i = 0; i < 10; i++) {
        vnum[i] = 0;
        vden[i] = 0;
    }
}

/* ---- Variable base: Montgomery ladder (key agreement) ------------------ */

static void x25519_ladder(uint8_t out[32], const uint8_t k[32], const uint8_t point[32]) {
    fe x1, x2, z2, x3, z3;
    fe A, AA, B, BB, E, C, D, DA, CB, t;
    fe_frombytes(x1, point);
    memset(x2, 0, sizeof x2);
    x2[0] = 1;
    memset(z2, 0, sizeof z2);
    memcpy(x3, x1, sizeof x3);
    memset(z3, 0, sizeof z3);
    z3[0] = 1;

    /* RFC 7748 section 5, step for step. */
    uint32_t swap = 0;
    for (int pos = 254; pos >= 0; pos--) {
        uint32_t bit = (k[pos >> 3] >> (pos & 7)) & 1;
        swap ^= bit;
        fe_cswap(x2, x3, swap);
        fe_cswap(z2, z3, swap);
        swap = bit;

        fe_add(A, x2, z2);
        fe_sq(AA, A);
        fe_sub(B, x2, z2);
        fe_sq(BB, B);
        fe_sub(E, AA, BB);
        fe_add(C, x3, z3);
        fe_sub(D, x3, z3);
        fe_mul(DA, D, A);
        fe_mul(CB, C, B);
        fe_add(t, DA, CB);
        fe_sq(x3, t);
        fe_sub(t, DA, CB);
        fe_sq(t, t);
        fe_mul(z3, x1, t);
        fe_mul(x2, AA, BB);
        fe_mul121665(t, E);
        fe_add(t, AA, t);
        fe_mul(z2, E, t);
    }
    fe_cswap(x2, x3, swap);
    fe_cswap(z2, z3, swap);

    fe_invert(z2, z2);
    fe_mul(x2, x2, z2);
    fe_tobytes(out, x2);

    /* The ladder state is secret. */
    volatile int32_t *vs[] = {x2, z2, x3, z3, A, AA, B, BB, E, C, D, DA, CB, t};
    for (size_t j = 0; j < sizeof vs / sizeof vs[0]; j++)
        for (int i = 0; i < 10; i++) vs[j][i] = 0;
}

void wtls_x25519(uint8_t out[32], const uint8_t scalar[32], const uint8_t point[32]) {
    static const uint8_t base[32] = {9};
    uint8_t k[32];
    memcpy(k, scalar, 32);
    k[0] &= 248;
    k[31] &= 127;
    k[31] |= 64;
    if (memcmp(point, base, 32) == 0) /* the point is public */
        x25519_base(out, k);
    else
        x25519_ladder(out, k, point);
    volatile uint8_t *vk = k;
    for (int i = 0; i < 32; i++) vk[i] = 0;
}
